    }
    // gpg exited non-zero for a legitimate domain reason (e.g. key not
    // found) — fall through to parseColonExpiry, which already handles
    // that case (pubCount == 0).
}

if err := parseColonExpiry(stdout.String(), keyID); err != nil {
    return fmt.Errorf("%w: %w", ErrKeyExpiryFinding, err)
}
return nil
```

